import{_ as e,c as p,o as t,ah as r}from"./chunks/framework.Dnh4IO1K.js";const d=JSON.parse('{"title":"7、【师】 坎下坤上","description":"周易阐真 - 7、【师】 坎下坤上","frontmatter":{"title":"7、【师】 坎下坤上","description":"周易阐真 - 7、【师】 坎下坤上"},"headers":[],"relativePath":"zh/classics/chanzhen/008.md","filePath":"zh/classics/chanzhen/008.md"}'),s={name:"zh/classics/chanzhen/008.md"};function n(c,a,i,o,h,l){return t(),p("div",null,[...a[0]||(a[0]=[r('<blockquote><p>彖曰：师，众也；贞，正也。能以众正，可以王矣。刚中而应，行险而顺，以此毒天下，而民从之，吉又何咎矣。</p></blockquote><h1 id="_7、【师】-坎下坤上" tabindex="-1">7、【师】 坎下坤上 <a class="header-anchor" href="#_7、【师】-坎下坤上" aria-label="Permalink to “7、【师】 坎下坤上”">​</a></h1><p>初六：师出以律，否臧凶。</p><p>九二：在师，中吉，无咎。王三锡命。</p><p>六三：师或舆尸，凶。</p><p>六四：师左次，无咎。</p><p>六五：田有禽，利执言，无咎。长子帅师，弟子舆尸，贞凶。</p><p>上六：大君有命，开国承家，小人勿用。</p><h2 id="孔易阐真-​" tabindex="-1">孔易阐真 ​ <a class="header-anchor" href="#孔易阐真-​" aria-label="Permalink to “孔易阐真 ​”">​</a></h2><p>大象：地中有水，师。君子以容民畜众。</p><p>师者，以一而帅众也。上坤地，下坎水，是地中有水也。地势厚大，水性滋润，地中有水，以一地而容众水，以众水而润一地，此师之象也。</p><p>君子有见于此，知人之身，如邦国也；人之心，如君也；身中之精神性情气；如民也，性中之仁义礼智信，如众也。此民此众，为人生之本，不可不保惜之。以是容民，以固根本，畜众以御外患焉。然必先容民者，先治内也；后畜众者，后治外也。治内以御外，治外以安内，内外相济，纵横逆顺，无不遂心，师之道如是，君子容畜之道亦如是也。</p><h2 id="悟元子注解-​" tabindex="-1">悟元子注解 ​ <a class="header-anchor" href="#悟元子注解-​" aria-label="Permalink to “悟元子注解 ​”">​</a></h2><p>否，方九反。长，下丈反。</p><p>师者，众也，以一人而统众人之义。卦德上坤顺，下坎险，顺而行险，故谓师。此借阳退阴之卦，承上需卦而来。需者，顺时进阳也，进阳所以为退阴计耳。退阴之法，以正除邪，以真灭假，犹如师贞。师者刑杀之道，须要有刚有柔，有仁有义，通权达变，方能济事。否则，能刚而不能柔，能柔而不能刚，或独仁而不知用义，或独义而不知行仁，皆不得正，不得正，即不得吉，反致其咎。惟老成练达之丈人，明善恶，分邪正，知吉凶，识急缓，刚柔不拘，仁义并行，行险能顺，顺以济险，借后天，返先天，依先天，化后天，不但阴气不能陷阳，而且群阴皆顺其阳，此吉而无咎之道。若非丈人，见理不明，邪正罔分，入于旁门曲径，冒然下手，不特不能退阴，而且有以助阴，取咎必矣。何能致吉成道乎！</p><p>夫人当先天未失之时，纯是天真，如国家太平，虽有智士良将，无所用之。及交后天，六贼作祸，七情猖狂，如国家有事，群寇作乱，若无刑杀剿除之道，不能反危为安。故金丹有为之道，煅去后天一切滓质，不使有纤微之疵，留于方寸之中，期必复见当年完完全全一个事物而后已。此师之道，所由贵也。</p><p>初六，在师之初，先要知其火候层次、进退规矩，循序而进，依法而行，能谨慎于始，自然决胜于终，如师出以律也。倘不明火候，冒然作为，如师无律，否臧自招其凶耳。此退阴贵明火候也。</p><p>九二，刚中有柔，有进有退，随时变通，不但不为阴气所伤，且能点化群阴，皆归于正，如在师中得吉，而又能无咎。然此师中之吉，系外炉加减之功，亦必内而心君诚一不二，内外相济，方能全吉而无咎。亦如王三锡命，君信臣而臣报君，未有不成其功者。此退阴必须内外相济也。</p><p>六三，不知火候进退之法，愚而自用，行险侥幸，欲求长生，反而促死，舆尸之凶，或者必有。此不知退阴而冒险者也。</p><p>六四，柔而居柔，自知无造命之学，不敢妄作妄为，自守本分，如师左次，虽不能致吉，亦可以无咎。此不能退阴而能守正者也。</p><p>六五，柔顺得中，虚心自处，物来顺应，使其客气自消自化，如田有禽，利执言也。然理服君子，法制小人，须要有刚有柔，方能济事。若独柔无刚，反能败事。长子帅师，柔以刚济能成事。弟子舆尸，独柔不刚能败事。此退阴必须刚柔相济也。</p><p>上六，在师之终，客气悉化，本固邦宁，心君安泰，无复用刑杀之道矣。然外邪既除，主人公稳坐中央，可以知其几希之微。一念善则存之，一念恶则去之，有功者赏，无功者罚，亦如大君有命，开国承家，小人勿用，必须拔去历劫轮回种子而后已。此退阴必须内外清静也。</p><p>六爻俱有退阴之道，吉凶不等，惟九二有刚有柔，通权达变，能以点化群阴，而不为群阴所伤，有为之功大矣哉！</p>',23)])])}const m=e(s,[["render",n]]);export{d as __pageData,m as default};
